    @EventHandler( payloadType=CreateAssetEvent.class )
    public void handle( CreateAssetEvent event) {
	    LOGGER.info("handling CreateAssetEvent - " + event );
	    Asset entity = new Asset();
            entity.setAssetId( event.getAssetId() );
            entity.setAssetTag( event.getAssetTag() );
            entity.setAssetName( event.getAssetName() );
            entity.setCommissioningDate( event.getCommissioningDate() );
            entity.setAssetStatus( event.getAssetStatus() );
	    
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    create(entity);
        
        // ------------------------------------------
    	// emit to subscribers that find all
    	// ------------------------------------------    	
        emitFindAllAsset( entity );
    }

