    /**
     * Method to retrieve the Asset via an AssetPrimaryKey.
     * @param 	id Long
     * @return 	Asset
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public Asset handle( FindAssetQuery query ) 
    throws ProcessingException, IllegalArgumentException {
    	return find( query.getFilter().getAssetId() );
    }
    
    /**
     * Method to retrieve a collection of all Assets
     *
     * @param	query	FindAllAssetQuery 
     * @return 	List<Asset> 
     * @exception ProcessingException Thrown if any problems
     */
    @SuppressWarnings("unused")
    @QueryHandler
    public List<Asset> handle( FindAllAssetQuery query ) throws ProcessingException {
    	return findAll( query );
    }



/**
 * emit to subscription queries of type FindAsset,
 * but only if the id matches
 *
 * @param		entity	Asset
 */
	protected void emitFindAsset( Asset entity ) {
		LOGGER.info("handling emitFindAsset" );
		
	    queryUpdateEmitter.emit(FindAssetQuery.class,
	                            query -> query.getFilter().getAssetId().equals(entity.getAssetId()),
	                            entity);
	}
	
	/**
	 * unconditionally emit to subscription queries of type FindAllAsset
	 * 
	 * @param		entity	Asset
	 */
	protected void emitFindAllAsset( Asset entity ) {
		LOGGER.info("handling emitFindAllAsset" );
		
	    queryUpdateEmitter.emit(FindAllAssetQuery.class,
	                            query -> true,
	                            entity);
	}

